import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100ZoneCountTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static void check(boolean b,String s){StarterDeck100PokemonTest.check(b,s);}
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static ServerMatch game(int n,String... opponentExtras){for(int seed=0;seed<200;seed++){
        var m=new ServerMatch(A,B,StarterDeck100PokemonTest.deck(A,n,id(398)),StarterDeck100PokemonTest.deck(B,1,opponentExtras),StarterDeck100CombatTest.RULE,StarterDeck100CombatTest.CARDS,StarterDeck100CombatTest.COMBAT,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicPokemon()).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.endTurn(A);m.endTurn(B);StarterDeck100PokemonTest.evolve(m,A,m.activePokemonView(A).pokemonId(),n);return m;
    }throw new AssertionError("No zone-count fixture");}
    static CardInstance hand(ServerMatch m,UUID player,String id){var found=m.privateView(player).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(found.isPresent())return found.get();var c=m.privateView(player).deck().stream().filter(x->x.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(player,List.of(c.instanceId()));return c;}
    public static void main(String[] args){detonate();forest();flames();searchlight();malformed();System.out.println("StarterDeck100ZoneCountTest passed: actual mill Energy counts, opponent Supporters, mandatory Basic Energy recovery and capped revealed-hand bonus");}
    static void detonate(){boolean sawSpecial=false;for(int seed=0;seed<30;seed++){
        var m=StarterDeck100PokemonTest.gameSeed(52,1,seed,"sm1_en_136");StarterDeck100PokemonTest.charge(m,0);var deck=m.privateView(A).deck();var top=List.copyOf(deck.subList(deck.size()-5,deck.size()));int energy=(int)top.stream().filter(c->m.cardDefinition(c.definitionId()).category()==CardCategory.ENERGY).count();sawSpecial|=top.stream().anyMatch(c->c.definitionId().equals("sm1_en_136"));m.attack(A,"max-detonate");check(m.lastAttack().finalDamage()==energy*200&&m.privateView(A).discard().containsAll(top),"Max Detonate counted old discard, non-Energy or units");if(sawSpecial)break;
    }check(sawSpecial,"fixture did not exercise Special Energy in top five");
        for(int left:List.of(0,1,3)){var m=StarterDeck100PokemonTest.game(52);StarterDeck100PokemonTest.charge(m,0);m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-left);var top=m.privateView(A).deck();int energy=(int)top.stream().filter(c->m.cardDefinition(c.definitionId()).category()==CardCategory.ENERGY).count();m.attack(A,"max-detonate");check(m.lastAttack().finalDamage()==energy*200&&m.privateView(A).deck().isEmpty(),"short/empty deck mill counted existing discard or failed");}
    }
    static void forest(){for(int count:List.of(0,2)){var m=game(29,id(398),id(373));var own=hand(m,A,id(398));m.discardHandCardsByEffect(A,A,List.of(own.instanceId()));m.endTurn(A);for(int i=0;i<count;i++){var c=hand(m,B,id(398));m.discardHandCardsByEffect(B,B,List.of(c.instanceId()));}for(String card:List.of(id(373),"sd100_cn_grass_energy")){var c=hand(m,B,card);m.discardHandCardsByEffect(B,B,List.of(c.instanceId()));}m.endTurn(B);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==count*40,"forest counted own discard/non-Supporter or base damage");}}
    static void flames(){for(boolean empty:List.of(false,true)){var m=StarterDeck100PokemonTest.game(65,"sm1_en_136");if(!empty){StarterDeck100ContinuationTest.discard(m,"sd100_cn_grass_energy",2);StarterDeck100ContinuationTest.discard(m,"sd100_cn_fire_energy",1);}StarterDeck100ContinuationTest.discard(m,"sm1_en_136",1);StarterDeck100PokemonTest.charge(m,0);int deck=m.privateView(A).deck().size();m.attack(A,"surging-flames");check(m.lastAttack().finalDamage()==(empty?40:160),"Surging Flames counted Special or wrong base");check(m.privateView(A).discard().size()==1&&m.privateView(A).discard().getFirst().definitionId().equals("sm1_en_136")&&m.privateView(A).deck().size()==deck+(empty?0:3),"Surging Flames did not return every Basic Energy only");}}
    static void searchlight(){for(int count:List.of(0,1,2)){var m=game(136,"sm1_en_136");m.endTurn(A);m.discardHandCardsByEffect(B,B,m.privateView(B).hand().stream().map(CardInstance::instanceId).toList());hand(m,B,id(1));for(int i=0;i<count;i++)hand(m,B,i==0?"sm1_en_136":"sd100_cn_grass_energy");m.endTurn(B);StarterDeck100PokemonTest.charge(m,1);m.attack(A,"searchlight-tail");var reveal=m.effectCardReveal();check(reveal!=null&&m.activePokemonView(B).damage()==0,"Searchlight damage preceded reveal");m.acknowledgeEffectReveal(A,reveal.id());check(m.lastAttack().finalDamage()==(count==0?90:180),"Searchlight did not cap any-Energy bonus at once");}}
    static void malformed(){var registry=EffectRegistry.standard();for(String json:List.of("{\"type\":\"discard_top_deck\",\"amount\":5,\"card_category\":\"ENERGY\"}","{\"type\":\"recover_all_discard\",\"target\":\"DISCARD\",\"card_category\":\"POKEMON\",\"basic_energy_only\":true,\"destination\":\"DECK_SHUFFLED\"}","{\"type\":\"damage_per_hand_card\",\"card_category\":\"ENERGY\",\"amount\":90,\"limit\":0}"))TopDeckLookTest.rejects(()->registry.parse(com.google.gson.JsonParser.parseString(json).getAsJsonObject()));}
}
